def verify():
    assert abs(0.6 / 4.2e6 * 1e7 - 1.4286) < 1e-3 and abs(math.pi * 100 * 1e-8 / (8e-3) * 1000 - 0.3927) < 1e-4
    assert abs(1e-6 / 1.43e-7 - 6.99) < 0.01 and abs(1e-7 * 1000 / 1e-4 - 1) < 1e-9 and abs(1e-9 * 100 / 1e-3 - 1e-4) < 1e-15
    assert abs(1e-6 / 1e-9 - 1000) < 1e-6 and abs(1e-6 / 1e-9 - 1000) < 1e-6 and abs(1 / 150 - 0.006667) < 1e-6 and abs(100 / 150 - 0.6667) < 1e-4


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
